#include "PluginEditor.h"
VocalClarityEditor::VocalClarityEditor(VocalClarityProcessor& p):AudioProcessorEditor(&p),processor(p),learnAttachment(p.parameters,"learn",learn){setSize(540,390);title.setText("VOCAL CLARITY",juce::dontSendNotification);title.setJustificationType(juce::Justification::centred);title.setFont(juce::Font(25.0f,juce::Font::bold));addAndMakeVisible(title);addAndMakeVisible(learn);
 const std::array<const char*,7> ids{"reduction","hiss","hum","clicks","sibilance","dereverb","mix"};const std::array<const char*,7> names{"NOISE REDUCTION","HISS","HUM","CLICKS","SIBILANCE","DE-REVERB","MIX"};
 for(size_t i=0;i<sliders.size();++i){auto& s=sliders[i];s.setSliderStyle(juce::Slider::RotaryHorizontalVerticalDrag);s.setTextBoxStyle(juce::Slider::TextBoxBelow,false,65,20);s.setRange(0,1,.01);s.setNumDecimalPlacesToDisplay(2);s.setRotaryParameters(juce::MathConstants<float>::pi*1.25f,juce::MathConstants<float>::pi*2.75f,true);labels[i].setText(names[i],juce::dontSendNotification);labels[i].setJustificationType(juce::Justification::centred);addAndMakeVisible(s);addAndMakeVisible(labels[i]);attachments.push_back(std::make_unique<Attachment>(p.parameters,ids[i],s));}}
void VocalClarityEditor::paint(juce::Graphics& g){g.fillAll(juce::Colour(0xff111813));g.setColour(juce::Colour(0xffa7e56b));g.drawRoundedRectangle(getLocalBounds().toFloat().reduced(8),14,2);}
void VocalClarityEditor::resized(){auto a=getLocalBounds().reduced(22);title.setBounds(a.removeFromTop(48));learn.setBounds(a.removeFromTop(40).withSizeKeepingCentre(180,32));a.removeFromTop(10);const int w=a.getWidth()/4,h=a.getHeight()/2;for(size_t i=0;i<sliders.size();++i){juce::Rectangle<int> cell(a.getX()+int(i%4)*w,a.getY()+int(i/4)*h,w,h);labels[i].setBounds(cell.removeFromTop(24));sliders[i].setBounds(cell.reduced(6));}}
